  FROM SALES
 GROUP BY CUBE(HOTEL, RTYPE);

-- (가)
SELECT COUNT(*) FROM (SELECT ROW_NUMBER() OVER (ORDER BY PRICE DESC) AS RK FROM ROOM)
 WHERE RK <= 3;

-- (나)
SELECT COUNT(*) FROM (SELECT RANK() OVER (ORDER BY PRICE DESC) AS RK FROM ROOM)
 WHERE RK <= 3;

-- (다)
SELECT COUNT(*) FROM (SELECT DENSE_RANK() OVER (ORDER BY PRICE DESC) AS RK FROM ROOM)
 WHERE RK <= 3;

